class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        import math
        N = int(math.isqrt(r)) + 1
        sieve = bytearray([1]) * (N + 1)
        sieve[0:2] = b'\x00\x00'
        for i in range(2, int(math.isqrt(N)) + 1):
            if sieve[i]:
                sieve[i*i::i] = bytearray(len(sieve[i*i::i]))
        cnt = 0
        p = 2
        for p in range(2, N + 1):
            if sieve[p] and l <= p * p <= r:
                cnt += 1
        return (r - l + 1) - cnt

