class Solution {
public:
    int nonSpecialCount(int l, int r) {
        int N = (int)sqrt((double)r) + 1;
        vector<bool> comp(N + 1, false);
        int cnt = 0;
        for (long long p = 2; p <= N; p++) {
            if (!comp[p]) {
                for (long long q = p * p; q <= N; q += p) comp[q] = true;
                if (p * p >= l && p * p <= r) cnt++;
            }
        }
        return (r - l + 1) - cnt;
    }
};

