import math, bisect
class Solution:
    _primes = None
    def nonSpecialCount(self, l: int, r: int) -> int:
        if Solution._primes is None:
            N = 31650
            sieve = bytearray([1]) * (N + 1)
            sieve[0:2] = b'\x00\x00'
            for i in range(2, math.isqrt(N) + 1):
                if sieve[i]:
                    sieve[i*i::i] = bytearray(len(sieve[i*i::i]))
            Solution._primes = [i for i in range(N + 1) if sieve[i]]
        ps = Solution._primes
        hi = bisect.bisect_right(ps, math.isqrt(r))
        lo = bisect.bisect_left(ps, math.isqrt(l - 1) + 1) if l > 1 else 2
        lo = bisect.bisect_left(ps, math.ceil(math.sqrt(l)))
        return (r - l + 1) - (hi - lo)

